'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const currency=n=>n==null?'Unavailable':new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',news:'<path d="M4 4h16v16H4zM8 8h8M8 12h8M8 16h5"/>',portfolio:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12h18M10 12v3h4v-3"/>',screener:'<path d="M3 5h18M6 12h12M10 19h4"/>',activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">${icons[k]||icons.news}</svg>`;
const universe={TCS:{name:'Tata Consultancy Services',sector:'Technology'},INFY:{name:'Infosys',sector:'Technology'},HDFCBANK:{name:'HDFC Bank',sector:'Banking'},ICICIBANK:{name:'ICICI Bank',sector:'Banking'},RELIANCE:{name:'Reliance Industries',sector:'Energy'},SUNPHARMA:{name:'Sun Pharmaceutical',sector:'Healthcare'},LT:{name:'Larsen & Toubro',sector:'Industrials'},ITC:{name:'ITC',sector:'Consumer'}};
const demoQuotes={TCS:4125,INFY:1840,HDFCBANK:1710,ICICIBANK:1265,RELIANCE:1460,SUNPHARMA:1780,LT:3575,ITC:440};
const initialHoldings=[{symbol:'TCS',quantity:18,average_cost:3820},{symbol:'INFY',quantity:30,average_cost:1670},{symbol:'HDFCBANK',quantity:50,average_cost:1560},{symbol:'RELIANCE',quantity:45,average_cost:1380},{symbol:'SUNPHARMA',quantity:22,average_cost:1610}];
const demoNews=[
 {id:'demo-1',title:'IT services: a large deal win raises questions about execution and margins',summary:'Illustrative scenario: a technology company announces a multi-year contract. Revenue recognition, delivery costs and existing valuation need further investigation.',symbols:['TCS','INFY'],source:'Synthetic scenario',published_at:null,retrieved_at:null,body:'',read_status:'Illustrative content',category:'Technology'},
 {id:'demo-2',title:'Banking update: loan growth outpaces deposit growth',summary:'Illustrative scenario: stronger lending may support income, while slower deposit growth could increase funding costs. Check the actual quarterly disclosures before drawing conclusions.',symbols:['HDFCBANK','ICICIBANK'],source:'Synthetic scenario',published_at:null,retrieved_at:null,body:'',read_status:'Illustrative content',category:'Banking'},
 {id:'demo-3',title:'Energy watch: changing crude prices create mixed business effects',summary:'Illustrative scenario: lower crude prices can benefit some operations while reducing upstream realisations. Segment exposure matters more than a single positive headline.',symbols:['RELIANCE'],source:'Synthetic scenario',published_at:null,retrieved_at:null,body:'',read_status:'Illustrative content',category:'Energy'},
 {id:'demo-4',title:'Pharma research: a product approval opens a potential growth avenue',summary:'Illustrative scenario: an approval is not a guarantee of sales. Competition, launch timing, compliance and pricing need to be examined.',symbols:['SUNPHARMA'],source:'Synthetic scenario',published_at:null,retrieved_at:null,body:'',read_status:'Illustrative content',category:'Healthcare'}];
let page='overview',horizon='short',period='1M',search='',sector='All sectors',busy=false;
let mode='demo',live=null,livePortfolio=null;
let holdings;try{holdings=JSON.parse(localStorage.getItem('marketlens-holdings'))||initialHoldings}catch{holdings=initialHoldings}
let watch;try{watch=JSON.parse(localStorage.getItem('marketlens-watch'))||['TCS','HDFCBANK']}catch{watch=['TCS','HDFCBANK']}
let log=[];let apiUrl=sessionStorage.getItem('marketlens-api')||'',token=sessionStorage.getItem('marketlens-token')||'';
let scanTime=null;
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
function stamp(s){if(!s)return 'Not available';const d=new Date(s);return isNaN(d)?'Not available':d.toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}
function safeLink(url){try{const p=new URL(url);return p.protocol==='https:'?p.href:null}catch{return null}}
function news(){return mode==='demo'?demoNews:(live?.news?.articles||[])}
function metrics(){if(mode==='live')return livePortfolio||{value:0,cost:0,pnl:0,holdings:[],sectors:[],alerts:[],complete:false};let value=0,cost=0,sectors={};const rows=holdings.map(h=>{const v=h.quantity*demoQuotes[h.symbol],c=h.quantity*h.average_cost;value+=v;cost+=c;const u=universe[h.symbol];sectors[u.sector]=(sectors[u.sector]||0)+v;return {...h,...u,price:demoQuotes[h.symbol],value:v,cost:c,pnl:v-c}});const weights=Object.entries(sectors).map(([sector,v])=>({sector,value:v,weight:value?v/value*100:0})).sort((a,b)=>b.weight-a.weight);return {value,cost,pnl:value-cost,complete:true,holdings:rows,sectors:weights,alerts:weights.filter(s=>s.weight>35).map(s=>`${s.sector} is ${s.weight.toFixed(1)}% of your portfolio, above the 35% review threshold.`)}}
async function api(path,body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),45000);try{const r=await fetch(apiUrl.replace(/\/$/,'')+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+token,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:controller.signal});let data;try{data=await r.json()}catch{throw new Error('Backend returned an invalid response')}if(!r.ok)throw new Error(typeof data.detail==='string'?data.detail:'Request failed ('+r.status+')');return data}finally{clearTimeout(timer)}}
async function refreshLive(){[live,livePortfolio]=await Promise.all([api('/api/state'),api('/api/portfolio')]);scanTime=live.last_scan}
function nav(name){page=name;search='';sector='All sectors';render();window.scrollTo(0,0)}
function render(){const m=metrics();$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">⌁</span>MarketLens<span style="color:var(--green)">.</span></div><div class="navlabel tiny">Your workspace</div><nav class="nav" aria-label="Main navigation">${[['overview','Overview'],['news','News intelligence'],['portfolio','My portfolio'],['screener','Research screener'],['activity','Research history']].map(([id,name])=>`<button data-nav="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id)}${name}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="planbox"><span class="pill">RESEARCH WORKSPACE</span><p>Better questions.<br>Clearer evidence.<br>Your decisions.</p><button class="linkbtn" data-nav="settings">Configure data sources ↗</button></div><nav class="nav"><button data-nav="settings" class="${page==='settings'?'active':''}">${icon('settings')}Connections</button></nav><div class="user"><div class="avatar">VS</div><div>Vishak's workspace<small>Personal research</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Workspace / <span>${({overview:'Overview',news:'News intelligence',portfolio:'My portfolio',screener:'Research screener',activity:'Research history',settings:'Connections'})[page]}</span></div><div class="top-right"><span class="muted" style="font-size:11px">INDIA · NSE universe</span><span class="mode"><i class="dot"></i>${mode==='demo'?'SAMPLE DATA':'BACKEND CONNECTED'}</span><button class="btn small" data-action="settings" aria-label="Connection settings">⚙</button></div></header><div class="content">${pageContent(m)}<footer class="foot"><span>MarketLens / Evidence before conviction.</span><span>Research tools · No trade execution · ${mode==='demo'?'All prices and stories are illustrative':'Check source timestamps and coverage'}</span></footer></div></main></div>`;bind()}
function heading(title,sub,action='scan',label='↻ Run research scan'){return `<div class="heading"><div><div class="eyebrow">Your market, in focus</div><h1>${title}</h1><p class="sub">${sub}</p></div><button class="btn primary ${busy?'loading':''}" data-action="${action}" ${busy?'disabled':''}>${busy?'Scanning…':label}</button></div>`}
function notice(){return mode==='demo'?`<div class="notice"><span class="tag">DEMO MODE</span><span>Explore with synthetic prices and news. This is a product demonstration, not current market analysis.</span><button class="linkbtn" data-action="settings" style="margin-left:auto;white-space:nowrap">Connect API ↗</button></div>`:`<div class="notice"><span class="tag">LIVE BACKEND</span><span>Last collection: ${stamp(scanTime)}. ${live?.news?.errors?.length||0} source errors. Prices require a separate, timestamped import.</span></div>`}
function stat(label,num,note,good=false){return `<div class="stat"><div class="stat-top">${label}<span>↗</span></div><div class="stat-num">${num}</div><div class="stat-note ${good?'positive':''}">${note}</div></div>`}
function pageContent(m){if(page==='overview')return overview(m);if(page==='portfolio')return portfolioView(m);if(page==='news')return newsView();if(page==='screener')return screener();if(page==='activity')return history();return settings()}
function overview(m){const n=news(),positive=m.pnl>=0;return heading('See the signal. Skip the noise.','Your portfolio, market developments and next research questions—in one place.')+notice()+`<section class="stats" aria-label="Portfolio summary">${stat('Portfolio value',currency(m.value),m.complete?'Across '+m.holdings.length+' holdings':'Partial valuation · missing quotes')}${stat('Unrealised return',`${positive?'+':''}${currency(m.pnl)}`,m.cost?`${positive?'+':''}${(m.pnl/(m.priced_cost||m.cost)*100).toFixed(2)}% on priced holdings`:'Import holdings to begin',positive)}${stat('News in your lens',n.length,mode==='demo'?'Illustrative scenarios':'Collected feed entries')}${stat('Portfolio review flags',m.alerts.length,m.alerts.length?'Concentration or data checks':'No concentration flags')}</section><div class="grid"><section class="panel"><div class="panel-head"><div><h2>Portfolio performance</h2><small>${mode==='demo'?'Illustrative trend · not historical market data':'Historical portfolio series not connected'}</small></div><div class="segmented">${['1W','1M','3M'].map(v=>`<button data-period="${v}" class="${period===v?'active':''}">${v}</button>`).join('')}</div></div>${chart()}<div class="insight">✧ &nbsp;${esc(m.alerts[0]||'Import holdings to reveal your portfolio exposure and research priorities.')}</div></section><section class="panel"><div class="panel-head"><h2>Your research brief</h2><span class="pill neutral">${mode==='demo'?'ILLUSTRATIVE':'EVIDENCE FIRST'}</span></div><div class="research-feature"><div class="feature-label"><span class="pill">PORTFOLIO CONTEXT</span><span class="pill amber">REVIEW</span></div><div class="feature-title">A headline is a starting point.<br>Not the whole thesis.</div><p class="feature-copy">Connect company developments to your holdings, inspect the source evidence, and understand what still needs verification.</p><div class="feature-foot"><span class="muted" style="font-size:11px">${n.length} ${mode==='demo'?'sample scenarios':'collected entries'}</span><button class="btn small" data-research="TCS">Open research brief ↗</button></div></div></section></div><div class="grid lower"><section class="panel"><div class="panel-head"><div><h2>On your radar</h2><small>Developments with portfolio context</small></div><button class="linkbtn" data-nav="news">All intelligence ↗</button></div>${n.slice(0,3).map(a=>newsRow(a)).join('')||'<div class="empty">Run a scan to collect source evidence.</div>'}</section><section class="panel"><div class="panel-head"><div><h2>Sector exposure</h2><small>${m.complete?'By market value':'Priced holdings only'}</small></div><span class="pill neutral">35% LIMIT</span></div>${sectors(m)}</section></div>`}
function chart(){if(mode==='live')return '<div class="empty" style="height:250px">No portfolio history yet.<br><small>Current valuation is available under My portfolio.</small></div>';const len=period==='1W'?7:period==='3M'?90:30;let pts=[];for(let i=0;i<len;i++){const y=155-i/(len-1)*95+Math.sin(i*1.8)*10+Math.cos(i*.7)*12;pts.push([i/(len-1)*660,y])}const path=pts.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');return `<div class="chart"><svg viewBox="0 0 680 210" role="img" aria-label="Synthetic portfolio trend for ${period}; demonstration only"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#a7e77a" stop-opacity=".2"/><stop offset="100%" stop-color="#a7e77a" stop-opacity="0"/></linearGradient></defs>${[35,85,135,185].map(y=>`<line x1="0" x2="670" y1="${y}" y2="${y}" stroke="#253034" stroke-dasharray="3 5"/>`).join('')}<path d="${path} L660,205 L0,205 Z" fill="url(#fill)"/><path d="${path}" fill="none" stroke="#b4ef86" stroke-width="2.5" stroke-linejoin="round"/><circle cx="660" cy="${pts.at(-1)[1]}" r="4" fill="#b4ef86"/></svg><div class="chart-labels"><span>Start of sample</span><span>Midpoint</span><span>End of sample</span></div><div class="chart-legend"><span><i></i>Sample portfolio</span><span>Synthetic series · ${len} points</span></div></div>`}
function sectors(m){const colors=['#b4ef86','#69cbb7','#809cce','#d6b47a','#ae90bd'];return `<div class="sector-body">${m.sectors.map((s,i)=>`<div class="sector-row"><div class="sector-info"><span><span style="color:${colors[i%5]}">●</span> ${esc(s.sector)}</span><span>${s.weight.toFixed(1)}%</span></div><div class="bar"><i style="width:${Math.min(100,s.weight)}%;background:${colors[i%5]}"></i></div></div>`).join('')||'<p class="muted">No priced holdings available.</p>'}<p style="font-size:11px;color:var(--muted);line-height:1.7">Exposure above your review threshold is a prompt to investigate, not an instruction to sell.</p></div>`}
function newsRow(a){return `<article class="news-row"><div class="news-icon">↗</div><div style="flex:1"><p class="news-title">${esc(a.title)}</p><div class="news-meta"><span>${esc(a.source)}</span><span>${a.published_at?stamp(a.published_at):'No publication timestamp'}</span>${a.symbols.map(s=>`<span class="positive">${esc(s)}</span>`).join('')}</div></div><button class="linkbtn" data-news="${esc(a.id)}" aria-label="Read story details">↗</button></article>`}
function newsView(){return heading('News with context.','Read the evidence. Understand the exposure. Track what changes.')+notice()+`<div class="filters"><input id="search" class="input" placeholder="Search companies or headlines…" value="${esc(search)}" aria-label="Search news"><select id="sector" aria-label="Filter sector">${['All sectors',...new Set(Object.values(universe).map(u=>u.sector))].map(s=>`<option ${s===sector?'selected':''}>${s}</option>`).join('')}</select><span class="pill neutral" style="align-self:center">${news().length} COLLECTED ITEMS</span></div>${mode==='live'?(live?.news?.errors||[]).map(e=>`<div class="notice">Source error: ${esc(e.source)} — ${esc(e.error)}. ${esc(e.detail||'')}</div>`).join(''):''}<div class="cardgrid" id="news-cards">${newsCards()}</div>`}
function newsCards(){return news().filter(a=>(a.title+' '+a.symbols.join(' ')).toLowerCase().includes(search.toLowerCase())&&(sector==='All sectors'||a.symbols.some(s=>universe[s]?.sector===sector))).map(a=>`<article class="newscard"><div style="display:flex;justify-content:space-between"><span class="pill">${esc(a.category||a.symbols.map(s=>universe[s]?.sector).filter(Boolean)[0]||'MARKET NEWS')}</span><span class="tiny">${mode==='demo'?'SAMPLE':'SOURCE FEED'}</span></div><h3>${esc(a.title)}</h3><p>${esc(a.summary)}</p><div class="news-meta"><span>${esc(a.source)}</span><span>${a.published_at?stamp(a.published_at):'Publication time unavailable'}</span></div><div style="display:flex;justify-content:space-between;align-items:center"><span class="muted" style="font-size:11px">${esc(a.symbols.join(' · ')||'No tracked company matched')}</span><button class="linkbtn" data-news="${esc(a.id)}">Inspect evidence ↗</button></div></article>`).join('')||'<div class="empty">No matching stories. Try another filter or run a scan.</div>'}
function portfolioView(m){return heading('Know what you own.','Holdings, concentration and the evidence that matters to your portfolio.','import','＋ Import holdings')+notice()+`<section class="stats">${stat('Market value',currency(m.value),m.complete?'Complete sample valuation':'Priced holdings only')}${stat('Invested capital',currency(m.cost),'Based on imported average costs')}${stat('Unrealised P&L',currency(m.pnl),'Excludes dividends, fees and taxes',m.pnl>=0)}${stat('Holdings',m.holdings.length,'Supported universe: 8 companies')}</section><section class="panel"><div class="panel-head"><h2>Your holdings</h2><button class="linkbtn" data-action="template">Download CSV template ↓</button></div><div class="tablewrap"><table><thead><tr><th>Company</th><th>Quantity</th><th>Avg. cost</th><th>Price</th><th>Value</th><th>P&L</th><th>Research</th></tr></thead><tbody>${m.holdings.map(h=>`<tr><td>${esc(h.symbol)}<small>${esc(h.name)}</small></td><td>${h.quantity}</td><td>${currency(h.average_cost)}</td><td>${currency(h.price)}<small>${mode==='demo'?'Synthetic price':stamp(h.as_of)}</small></td><td>${currency(h.value)}</td><td class="${h.pnl>=0?'positive':'negative'}">${currency(h.pnl)}</td><td><button class="btn small" data-research="${esc(h.symbol)}">Inspect ↗</button></td></tr>`).join('')||'<tr><td colspan="7">Import your holdings to get started.</td></tr>'}</tbody></table></div></section><div class="grid lower"><section class="panel"><div class="panel-head"><h2>Portfolio review</h2></div><div style="padding:0 22px 22px">${m.alerts.map(a=>`<div class="notice">${esc(a)}</div>`).join('')||'<p class="muted">No concentration flags in the priced holdings.</p>'}<p class="muted" style="font-size:12px">Risk is broader than sector concentration. Correlation, liquidity, investment horizon and financial goals need separate assessment.</p></div></section><section class="panel"><div class="panel-head"><h2>Allocation</h2></div>${sectors(m)}</section></div>`}
function screener(){return heading('Research starts with a question.','Transparent criteria, separate horizons, and evidence you can inspect.')+notice()+`<div class="filters"><div class="segmented"><button data-horizon="short" class="${horizon==='short'?'active':''}">Short-term · trend</button><button data-horizon="long" class="${horizon==='long'?'active':''}">Long-term · fundamentals</button></div><select id="sector" aria-label="Filter sector">${['All sectors',...new Set(Object.values(universe).map(u=>u.sector))].map(s=>`<option ${sector===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="notice"><span class="tag">METHOD</span>${horizon==='short'?'Trend score: above 20-day average + 20/50-day trend + positive 20-day momentum. No liquidity or volume model yet.':'Long-term rankings are unavailable until verified fundamentals and valuation data are connected.'}</div><section class="panel"><div class="panel-head"><h2>${horizon==='short'?'Research universe':'Long-term evidence checklist'}</h2><span class="muted" style="font-size:11px">No profit probability implied</span></div><div class="tablewrap"><table><thead><tr><th>Company</th><th>Sector</th><th>Trend score</th><th>Evidence</th><th>Status</th><th>Watch</th><th></th></tr></thead><tbody>${Object.entries(universe).filter(([s,u])=>sector==='All sectors'||u.sector===sector).map(([s,u],i)=>{const count=news().filter(a=>a.symbols.includes(s)).length;const score=mode==='demo'&&horizon==='short'?[90,80,60,70,50,80,60,50][i]:null;return `<tr><td>${s}<small>${esc(u.name)}</small></td><td>${u.sector}</td><td><span class="score">${score??'—'}</span><small>${score!=null?'Sample score':'Not calculated'}</small></td><td>${count} ${mode==='demo'?'scenarios':'items'}</td><td><span class="pill ${score>=80?'':'neutral'}">${score>=80?'Sample candidate':'Needs research'}</span></td><td><button class="linkbtn" data-watch="${s}" aria-label="${watch.includes(s)?'Remove from':'Add to'} watchlist">${watch.includes(s)?'★':'☆'}</button></td><td><button class="btn small" data-research="${s}">Research ↗</button></td></tr>`}).join('')}</tbody></table></div></section>`}
function history(){const reports=mode==='live'?(live?.reports||[]):log.filter(l=>l.type==='report');return heading('A record of your reasoning.','Review the evidence and limitations behind each research session.','export','↓ Export research')+notice()+`<section class="panel"><div class="panel-head"><h2>Research activity</h2><span class="pill neutral">${reports.length} REPORTS</span></div>${log.filter(l=>l.type==='scan').map(l=>`<div class="activity"><div class="activity-number">↻</div><div><h3>${esc(l.title)}</h3><p>${stamp(l.time)} · ${esc(l.detail)}</p></div></div>`).join('')}${reports.map((r,i)=>`<div class="activity"><div class="activity-number">${i+1}</div><div style="flex:1"><h3>${esc(r.symbol)} · ${esc(r.horizon==='short'?'Short-term':'Long-term')} research</h3><p>${stamp(r.generated_at||r.time)} · ${esc(r.conclusion)} · ${r.evidence_count||0} evidence items</p></div><button class="linkbtn" data-report="${i}">Open ↗</button></div>`).join('')||'<div class="empty">Your research trail starts here.<br><small>Open a company brief to create your first report.</small></div>'}</section>`}
function settings(){return heading('Connect your research engine.','The dashboard is ready. Connect your own FastAPI backend for live collection.','connect','Configure connection')+`<div class="grid"><section class="panel settings-card"><span class="pill">${mode==='demo'?'SAMPLE MODE ACTIVE':'API CONNECTED'}</span><h2 style="margin-top:18px">Data connections</h2><p>This hosted dashboard starts with synthetic data. The included Python backend collects configured RSS feeds, optionally reads permitted articles, and stores research reports.</p><div class="activity"><span class="positive">01</span><div><h3>News and article collection</h3><p>Allowlisted HTTPS sources; robots-aware article reading. Enable READ_ARTICLES in the backend configuration.</p></div></div><div class="activity"><span class="positive">02</span><div><h3>Market prices</h3><p>Import timestamped closing-price series through the API. A licensed market-data provider is not connected.</p></div></div><div class="activity"><span class="positive">03</span><div><h3>Scheduled checks</h3><p>Celery Beat and RabbitMQ run hourly on weekdays from 08:30 to 17:30 IST when deployed. Exchange holidays are not filtered yet.</p></div></div><div class="activity"><span class="positive">04</span><div><h3>Evidence workflow</h3><p>LangGraph orchestrates deterministic research. No LLM is connected; the system does not claim AI-generated financial judgement.</p></div></div><button class="btn primary" data-action="connect">Configure backend ↗</button> <button class="btn" data-action="demo">Use sample mode</button></section><section class="panel settings-card"><h2>Built for inspectable decisions</h2><p>Every live report preserves its evidence links, collection times, horizon, model method and missing-data warnings.</p><h3 style="margin-top:25px">This first release</h3><p>Single-owner API token access. CSV portfolios. Daily-close trend screening. Eight-company universe. Explicit missing-data handling.</p><h3 style="margin-top:25px">Before a paid launch</h3><p>Add user accounts and tenant isolation, licensed price and fundamental feeds, monitoring, strategy evaluation, and review the regulatory requirements for the intended service.</p><h3 style="margin-top:25px">Your local portfolio</h3><p>Sample-mode holdings stay in this browser. Connecting the API does not automatically upload them. API credentials are held in session storage.</p><button class="btn" data-action="reset">Reset sample workspace</button></section></div>`}
function openModal(html){$('#modal').innerHTML=html;$('#modal').showModal();$('#modal').querySelector('[data-close]')?.addEventListener('click',()=>$('#modal').close())}
function modalTitle(title,sub=''){return `<div class="modalhead"><div><div class="eyebrow">MarketLens / Research workspace</div><h2>${title}</h2>${sub?`<p class="sub" style="margin-top:9px">${sub}</p>`:''}</div><button class="close" data-close aria-label="Close dialog">✕</button></div>`}
function showNews(id){const a=news().find(a=>a.id===id);if(!a)return;const link=safeLink(a.url);openModal(modalTitle(esc(a.title))+`<span class="pill neutral">${esc(a.source)}</span><p>${esc(a.summary)}</p><div class="report-section"><h3>Evidence status</h3><p>${esc(a.read_status||'Feed excerpt only')}<br>Published: ${stamp(a.published_at)}<br>Collected: ${stamp(a.retrieved_at)}</p>${a.body?`<p>${esc(a.body.slice(0,2200))}</p>`:''}${link?`<a href="${esc(link)}" target="_blank" rel="noopener noreferrer">Read original source ↗</a>`:'<p class="muted">Synthetic scenario. No real announcement or source article is implied.</p>'}</div><div class="report-section"><h3>Related companies</h3>${a.symbols.map(s=>`<button class="btn small" data-related="${s}">${s} ↗</button>`).join(' ')||'<p>No tracked company matched.</p>'}</div>`);document.querySelectorAll('[data-related]').forEach(b=>b.onclick=()=>{$('#modal').close();research(b.dataset.related)})}
function reportModal(r){openModal(modalTitle(`${esc(r.symbol)} / ${r.horizon==='short'?'Short-term':'Long-term'} brief`,esc(universe[r.symbol]?.name||''))+`<div class="feature-label"><span class="pill amber">${esc(r.conclusion)}</span><span class="pill neutral">${mode==='demo'?'SYNTHETIC DEMO':esc(r.engine)}</span></div><p>${esc(r.reason)}</p><div class="report-section"><h3>What the data supports</h3><p>${r.technical?.available?`Trend score: ${r.technical.score}/100 · 20-day momentum: ${r.technical.momentum_20d}%<br>${esc(r.technical.method||'Synthetic demonstration only')}`:esc(r.technical?.reason||'Price history not available.')}</p></div><div class="report-section"><h3>Evidence / ${r.evidence?.length||0} items</h3>${(r.evidence||[]).map(a=>`<div class="evidence"><h3>${esc(a.title)}</h3><p>${esc(a.excerpt||'Inspect the original reporting.')}</p><p class="muted">Published: ${stamp(a.published_at)} · Collected: ${stamp(a.retrieved_at)}</p>${safeLink(a.url)?`<a href="${esc(safeLink(a.url))}" target="_blank" rel="noopener noreferrer">Original source ↗</a>`:'<span class="pill neutral">ILLUSTRATIVE SCENARIO</span>'}</div>`).join('')||'<p>No matching evidence. A positive ranking cannot be justified.</p>'}</div><div class="report-section"><h3>Risks and missing information</h3><ul>${(r.risks||[]).map(v=>`<li>${esc(v)}</li>`).join('')}</ul><h3>Revisit this conclusion when</h3><p>${esc(r.invalidation)}</p><p class="muted">Generated ${stamp(r.generated_at)}. Research priority, not an instruction to trade.</p></div>`)}
async function research(symbol){if(busy)return;busy=true;try{let r;if(mode==='live'){toast('Building evidence brief…');r=await api('/api/research',{symbol,horizon});await refreshLive()}else{const matches=news().filter(a=>a.symbols.includes(symbol));r={type:'report',symbol,horizon,generated_at:new Date().toISOString(),conclusion:'Illustrative research brief',engine:'Demo',technical:{available:false,reason:'Synthetic prices are not a validated historical series.'},evidence:matches.map(a=>({...a,excerpt:a.summary})),evidence_count:matches.length,reason:'This example shows how a research report connects developments to a company. It is not current analysis or a buy/sell recommendation.',risks:['All scenario headlines and prices in sample mode are fictional.','Verified filings, valuation, fundamentals and historical market data are required.','A favourable headline does not establish an investment opportunity.'],invalidation:'Replace sample data with verified, timestamped sources before using the workflow for research.'};log.unshift(r)}render();reportModal(r)}catch(e){toast(e.message)}finally{busy=false}}
async function scan(){if(busy)return;busy=true;render();try{if(mode==='live'){const result=await api('/api/scan',{});await refreshLive();log.unshift({type:'scan',title:'Source collection completed',time:new Date().toISOString(),detail:`${result.articles.length} entries, ${result.errors.length} source errors`});toast(result.errors.length?`Scan finished with ${result.errors.length} source errors. See history.`:`Collected ${result.articles.length} source entries`)}else{await new Promise(r=>setTimeout(r,900));scanTime=new Date().toISOString();log.unshift({type:'scan',title:'Sample scan completed',time:scanTime,detail:'4 illustrative scenarios evaluated; no live news was fetched'});toast('Sample scan complete. Connect a backend to collect live news.')}}catch(e){toast('Scan failed: '+e.message)}finally{busy=false;render()}}
function download(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function importDialog(){openModal(modalTitle('Import your holdings','CSV columns: symbol,quantity,average_cost')+`<p class="muted">Supported: ${Object.keys(universe).join(', ')}. Combine multiple lots into one row per symbol. Average costs and quantities must be positive.</p><div class="upload-zone"><label for="csv-file">Choose a CSV file (maximum 150 KB)</label><input id="csv-file" type="file" accept=".csv,text/csv"><p id="import-status" role="status" class="muted"></p></div><p class="muted">${mode==='demo'?'Imported holdings stay in this browser and use synthetic demo prices.':'The file is sent to your connected backend.'}</p>`);$('#csv-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>150000)throw new Error('File exceeds 150 KB');const text=await f.text();if(mode==='live'){const result=await api('/api/portfolio/import',{content:text});await refreshLive();toast(`Imported ${result.imported} holdings`)}else{const rows=parseCsv(text);holdings=rows;localStorage.setItem('marketlens-holdings',JSON.stringify(rows));toast(`Imported ${rows.length} holdings with sample prices`)}$('#modal').close();render()}catch(err){$('#import-status').textContent=err.message}}}
function parseCsv(text){const lines=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/);const head=lines.shift().split(',').map(s=>s.trim());const required=['symbol','quantity','average_cost'];if(required.some(k=>!head.includes(k)))throw new Error('Required columns: symbol,quantity,average_cost');const seen=new Set;const rows=lines.filter(l=>l.trim()).map((line,i)=>{const cells=line.split(',').map(s=>s.trim().replace(/^"|"$/g,''));const s=cells[head.indexOf('symbol')].toUpperCase(),q=Number(cells[head.indexOf('quantity')]),c=Number(cells[head.indexOf('average_cost')]);if(!universe[s])throw new Error(`Line ${i+2}: unsupported symbol ${s}`);if(seen.has(s))throw new Error(`Duplicate ${s}; combine lots first`);seen.add(s);if(!Number.isFinite(q)||!Number.isFinite(c)||q<=0||c<=0)throw new Error(`Line ${i+2}: quantity and cost must be positive numbers`);return {symbol:s,quantity:q,average_cost:c}});if(!rows.length||rows.length>500)throw new Error('Import between 1 and 500 holdings');return rows}
function connectionDialog(){openModal(modalTitle('Connect FastAPI backend','Use your own deployed HTTPS endpoint, or run the dashboard from the local API.')+`<label for="api-url">Backend URL</label><input class="input" id="api-url" type="url" placeholder="https://your-api.example.com" value="${esc(apiUrl)}"><label for="api-token">API token</label><input class="input" id="api-token" type="password" autocomplete="off" value="${esc(token)}"><p class="muted" style="font-size:12px">Credentials stay in session storage. Configure CORS on your backend for this dashboard's origin. Sample holdings are not uploaded automatically.</p><p id="connect-status" role="status" class="muted"></p><button class="btn primary" id="connect-submit">Test and connect ↗</button>`);$('#connect-submit').onclick=async()=>{const old={apiUrl,token};try{const url=new URL($('#api-url').value);if(url.protocol!=='https:'&&!(url.protocol==='http:'&&['localhost','127.0.0.1'].includes(url.hostname)&&location.protocol==='http:'))throw new Error('Use HTTPS, or local HTTP when the dashboard is also local.');apiUrl=url.origin;token=$('#api-token').value;if(!token)throw new Error('Enter your API token');$('#connect-status').textContent='Checking connection…';await refreshLive();sessionStorage.setItem('marketlens-api',apiUrl);sessionStorage.setItem('marketlens-token',token);mode='live';$('#modal').close();render();toast('Backend connected. No sample data is included in live mode.')}catch(e){apiUrl=old.apiUrl;token=old.token;$('#connect-status').textContent=e.message}}}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actions[b.dataset.action]?.());document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{period=b.dataset.period;render()});document.querySelectorAll('[data-horizon]').forEach(b=>b.onclick=()=>{horizon=b.dataset.horizon;render()});document.querySelectorAll('[data-news]').forEach(b=>b.onclick=()=>showNews(b.dataset.news));document.querySelectorAll('[data-research]').forEach(b=>b.onclick=()=>research(b.dataset.research));document.querySelectorAll('[data-watch]').forEach(b=>b.onclick=()=>{const s=b.dataset.watch;watch=watch.includes(s)?watch.filter(v=>v!==s):[...watch,s];localStorage.setItem('marketlens-watch',JSON.stringify(watch));render()});document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>reportModal((mode==='live'?live.reports:log.filter(l=>l.type==='report'))[Number(b.dataset.report)]));$('#sector')?.addEventListener('change',e=>{sector=e.target.value;render()});$('#search')?.addEventListener('input',e=>{search=e.target.value;$('#news-cards').innerHTML=newsCards();document.querySelectorAll('[data-news]').forEach(b=>b.onclick=()=>showNews(b.dataset.news))})}
const actions={scan,import:importDialog,settings:()=>nav('settings'),connect:connectionDialog,demo:()=>{mode='demo';render();toast('Sample mode enabled')},template:()=>download('marketlens_holdings_template.csv','symbol,quantity,average_cost\nTCS,10,3800\nHDFCBANK,20,1550\n','text/csv'),export:async()=>{try{const data=mode==='live'?await api('/api/export'):{mode:'synthetic demo',exported_at:new Date().toISOString(),portfolio:metrics(),reports:log};download('marketlens_research.json',JSON.stringify(data,null,2),'application/json');toast('Research exported')}catch(e){toast(e.message)}},reset:()=>{if(!confirm('Reset sample holdings, watchlist and session research history?'))return;holdings=initialHoldings;watch=['TCS','HDFCBANK'];log=[];localStorage.removeItem('marketlens-holdings');localStorage.removeItem('marketlens-watch');render();toast('Sample workspace reset')}};
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});render();
